def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if number == 0:
        return 0.0

    guess = number
    while True:
        new_guess = 0.5 * (guess + number / guess)
        if abs(new_guess - guess) < 1e-10:  # stopping condition with small tolerance
            break
        guess = new_guess
    return new_guess

