def cal_sum(n):
    if n < 1:
        return 0
    elif n == 1 or n == 2:
        return 1
    elif n == 3:
        return 2

    sequence = [1, 1, 2]
    for i in range(3, n):
        next_num = sequence[i-3] + sequence[i-2]
        sequence.append(next_num)

    return sum(sequence)

