def large_product(nums1, nums2, N):
    nums1_sorted = sorted(nums1, reverse=True)
    nums2_sorted = sorted(nums2, reverse=True)

    max_products = []
    heap = []

    for i in range(N):
        if i < len(nums1_sorted) and i < len(nums2_sorted):
            product = nums1_sorted[i] * nums2_sorted[i]
            max_products.append(product)
        else:
            break

    for i in range(N):
        for j in range(i + 1, N):
            if i < len(nums1_sorted) and j < len(nums2_sorted):
                alternative_product = nums1_sorted[i] * nums2_sorted[j]
                if alternative_product > max_products[i]:
                    max_products[i] = alternative_product

    max_products.sort(reverse=True)
    return max_products[:N]

