def find_Max_Num(arr):
    # Convert all elements to strings to facilitate comparison
    arr_str = list(map(str, arr))

    # Custom comparator to sort the numbers in descending order
    from functools import cmp_to_key
    def compare(a, b):
        if a + b > b + a:
            return -1
        else:
            return 1
    arr_str.sort(key=cmp_to_key(compare))

    # Edge case: if sorted array is ['0000...'] then the max number is '0'
    if arr_str[0] == '0':
        return 0

    # Join the list into a single string and convert back to integer
    result_str = ''.join(arr_str)
    return int(result_str)
```

