def check_Consecutive(l):
    if not l:
        return False

    l_sorted = sorted(l)
    n = len(l_sorted)

    # Check if the list is empty or has only one element
    if n == 1:
        return True

    # Check if all elements are within the expected consecutive range
    min_val = l_sorted[0]
    max_val = l_sorted[-1]

    if (max_val - min_val + 1) != n:
        return False

    # Check every element is exactly where it should be for a consecutive sequence
    for i in range(n):
        if l_sorted[i] != min_val + i:
            return False

    return True

