def comb_sort(nums):
    gap = len(nums)
    shrink = 1.3
    sorted = False

    while not sorted or gap > 1:
        gap = max(1, int(gap // shrink))
        sorted = True

        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted = False
