def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result = {}
    fields = []

    # Split fields handling quoted sections
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '\\' and in_quotes:
            current_field += char  # Escape next character
        elif char == '"':
            if in_quotes:
                in_quotes = False
            else:
                in_quotes = True
                if current_field:  # Add any text before the quote
                    fields.append(current_field)
                    current_field = ""
        else:
            current_field += char

        if char == ';' and not in_quotes:
            fields.append(current_field)
            current_field = ""

    if current_field:  # Add the last field
        fields.append(current_field)

    # Process each field
    for field in fields:
        if not field.strip():
            continue

        if '=' not in field:
            # Bare key
            key = field.strip()
            result[key] = True
        else:
            # Key=value
            key_part, value_part = field.split('=', 1)
            key = key_part.strip()

            if value_part.startswith('"') and value_part.endswith('"'):
                # Quoted value - remove quotes and handle escapes
                quoted_value = value_part[1:-1]
                unquoted_value = []
                i = 0
                while i < len(quoted_value):
                    if quoted_value[i] == '\\' and i + 1 < len(quoted_value):
                        if quoted_value[i+1] == '"':
                            unquoted_value.append('"')
                            i += 2
                        else:
                            unquoted_value.append(quoted_value[i:i+2])
                            i += 2
                    else:
                        unquoted_value.append(quoted_value[i])
                        i += 1
                value = ''.join(unquoted_value)
            else:
                # Unquoted value
                value = value_part.strip()
                if value == '':
                    value = True

            result[key] = value

    return result
```

