def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    """Returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less than 100.
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False

    # Function to split a into a list of its prime factors
    def prime_factors(n):
        factors = []
        # Check for divisibility by 2
        while n % 2 == 0:
            factors.append(2)
            n = n // 2
        # Check for odd divisors up to sqrt(n)
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors.append(i)
                n = n // i
            i = i + 2
        if n > 2:
            factors.append(n)
        return factors

    factors_list = prime_factors(a)
    if len(factors_list) != 3:
        return False

    # Ensure all three factors are distinct and prime
    unique_factors = list(set(factors_list))
    return len(unique_factors) == 3 and all(is_prime(f) for f in unique_factors)
