def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result = {}
    field_start = 0
    in_quotes = False
    escape_next = False

    for i, char in enumerate(line + ';'):  # Add sentinel ';'
        if escape_next:
            escape_next = False
            continue

        if char == '\\' and i + 1 < len(line):
            escape_next = True
            continue

        if char == '"':
            in_quotes = not in_quotes
        elif char == ';' and not in_quotes:
            field = line[field_start:i]
            if field.strip():  # Ignore empty fields
                parsed = _parse_field(field)
                if parsed:
                    result[parsed[0]] = parsed[1]
            field_start = i + 1

    return result

def _parse_field(field):
    if '=' in field:
        key, value = field.split('=', 1)
    else:
        key = field
        value = True

    key = key.strip()

    if value is True:
        return (key, True)

    value_parts = value.split('"', 1)
    if len(value_parts) == 3 and value_parts[0] == '=':
        # This handles the case where value starts with '='
        unquoted = value_parts[1].split('"', 1)
        if len(unquoted) == 2:
            value = unquoted[1]
        else:
            value = value_parts[1]
    else:
        if len(value_parts) == 1:
            value = value_parts[0].strip()
        else:
            if value_parts[0] == '=':
                # If value starts with '=', don't strip
                value = value_parts[1]
            else:
                quote_content = value_parts[1]
                if len(value_parts) > 2:
                    quote_content += '"' + value_parts[2]
                value = quote_content

    # Process escaped quotes in value if it's wrapped in quotes
    if value and value.startswith('"') and not value.endswith('"'):
        # Handle cases where quotes start properly but end in the field
        value = value[1:]

    return (key, _process_value(value))

def _process_value(value):
    if not value or not value.startswith('"'):
        return value.strip()

    # Process quoted value
    content = value[1:-1]  # Remove surrounding quotes
    output = []
    i = 0
    while i < len(content):
        if i + 1 < len(content) and content[i] == '\\' and content[i+1] == '"':
            output.append('"')
            i += 2
        else:
            output.append(content[i])
            i += 1
    return ''.join(output)
```

