def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Square root of negative number is not a real number")

    if number == 0:
        return 0

    guess = number / 2
    while True:
        new_guess = (guess + number / guess) / 2
        if abs(new_guess - guess) < 1e-10:
            break
        guess = new_guess
    return new_guess
```

