def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    result = {}
    fields = line.split(';')

    for field in fields:
        field = field.strip()
        if not field:
            continue

        if '=' in field:
            key_part, value_part = field.split('=', 1)
            key = key_part.strip()
            value_part = value_part.strip()

            if value_part.startswith('"'):
                # Handle quoted value
                if len(value_part) >= 2 and value_part.endswith('"'):
                    # Simple quoted case
                    value = value_part[1:-1].replace('\\"', '"').replace('""', '"')
                else:
                    # Unmatched quote, treat as unquoted
                    value = value_part.lstrip('"')
                    value = value.rstrip('"') if value.endswith('"') else value
            else:
                # Unquoted value
                value = value_part

            # Process escaped quotes and remove surrounding quotes if any
            if isinstance(value, str):
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1].replace('\\"', '"') if '\\"' in value else value[1:-1]
                if '\\"' in value:
                    value = value.replace('\\"', '"')

            result[key] = value if value != '' else True
        else:
            # Bare key with True value
            key = field
            result[key] = True

    return result
